changeSet.sql:
-- Канон каждого имени = самая старая строка (минимальный created_at,
-- tie-break по id). Маппинг dup_id -> canonical_id.
CREATE TEMP TABLE authority_canon AS
SELECT a.id AS dup_id, c.canonical_id
FROM authorities a
JOIN (
    SELECT name, (
        SELECT id FROM authorities a2
        WHERE a2.name = a1.name
        ORDER BY created_at, id
        LIMIT 1
    ) AS canonical_id
    FROM authorities a1
    GROUP BY name
) c ON a.name = c.name
WHERE a.id <> c.canonical_id;

-- Чистим дубли-пары в hadith_grades (UNIQUE(source_id, scholar_id))
-- ДО repoint, иначе repoint нарушил бы constraint.
DELETE FROM hadith_grades hg
USING authority_canon ac
WHERE hg.scholar_id = ac.dup_id
  AND EXISTS (
    SELECT 1 FROM hadith_grades hg2
    WHERE hg2.source_id = hg.source_id
      AND hg2.scholar_id = ac.canonical_id
  );

-- Repoint оставшихся FK на канон.
UPDATE hadith_grades hg SET scholar_id = ac.canonical_id
FROM authority_canon ac WHERE hg.scholar_id = ac.dup_id;

UPDATE sources s SET authority_id = ac.canonical_id
FROM authority_canon ac WHERE s.authority_id = ac.dup_id;

UPDATE lib_books b SET authority_id = ac.canonical_id
FROM authority_canon ac WHERE b.authority_id = ac.dup_id;

-- Удалить дубли-authorities (FK уже перенаправлены).
DELETE FROM authorities a USING authority_canon ac WHERE a.id = ac.dup_id;

DROP TABLE authority_canon;

-- UNIQUE index заменяет старый non-unique (lookup идентичен).
DROP INDEX IF EXISTS idx_authorities_name;
CREATE UNIQUE INDEX idx_authorities_name ON authorities(name);
